# Generated by build.py from recipe.yml for recipe redis-seed-a-cache-for-a-test. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/products.json'), "{`"items`":[`"tea`",`"coffee`"]}`n")
[IO.File]::WriteAllText((Join-Path $PWD 'seed.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Seeds the settings and a cached copy that lives three seconds, reads them as the app would,`n# waits until the copy has expired, and reads again, then asks the origin over HTTP.`n# Usage: sh seed.sh <redis port> <http port>`nr=redis://127.0.0.1:`$1`nh=http://127.0.0.1:`$2`ncurl -s -u alice:s3cret `"`$r/SET/settings:currency/EUR`" `"`$r/SET/cache:products/cached-copy/PX/3000`" \`n  `"`$r/GET/settings:currency`" `"`$r/GET/cache:products`" | {`n  read -r set1; read -r set2; read -r currency; read -r cached`n  echo `"settings:currency: `$currency`"`n  echo `"cache:products: `$cached`"`n}`nsleep 4`ncurl -s -u alice:s3cret `"`$r/GET/settings:currency`" `"`$r/GET/cache:products`" | {`n  read -r currency; read -r cached`n  echo `"settings:currency: `$currency`"`n  echo `"cache:products: [`$cached]`"`n}`necho `"origin: `$(curl -s -u alice:s3cret `"`$h/products.json`")`"`n")
$server0 = Start-Process surl -ArgumentList '--user', 'alice:s3cret', '--allow-plaintext-auth', '--directory', 'site', 'redis://127.0.0.1:8080', 'http://127.0.0.1:8081' -PassThru -NoNewWindow
Start-Sleep 1
try { sh seed.sh 8080 8081 } finally { Stop-Process $server0 }
